// ============================================================
// MiniMind — data/TinyStoriesDataset.ts
// ============================================================
// TinyStoriesDataset — loads the TinyStories corpus for GPT training.
//
// TinyStories (Eldan & Li, 2023) is a synthetic dataset of short
// children's stories generated by GPT-3.5 and GPT-4. It's designed
// for training small language models (1-10M params) and is widely
// used for validating GPT architectures at small scale.
//
// Dataset info:
//   - ~2.7M stories in TinyStories (full)
//   - ~150K stories in TinyStories-train (subset)
//   - Each story is 50-500 words, simple vocabulary
//   - JSONL format: {"story": "Once upon a time..."}
//
// This adapter:
//   1. Downloads TinyStories from HuggingFace or a configured mirror
//   2. Caches the raw JSONL file locally
//   3. Parses stories into a TextCorpus
//   4. Provides tokenizer-aware sample generation
//
// Usage:
//   const ds = await TinyStoriesDataset.load({
//     split: "train",
//     maxStories: 1000,
//   });
//   for (const story of ds) {
//     console.log(story.substring(0, 100));
//   }
// ============================================================

import * as fs from "fs";
import * as path from "path";
import { TextCorpus } from "./TextCorpus";
import type { ITokenizer } from "./ITokenizer";

// ============================================================
// Types
// ============================================================

export interface TinyStoriesConfig {
  /** Dataset split: "train" (~2.7M) or "validation" (~22K) */
  split?: "train" | "validation";
  /** Maximum number of stories to load (default: unlimited) */
  maxStories?: number;
  /** Cache directory for downloaded files (default: .cache/minimind/) */
  cacheDir?: string;
  /** Override URL for the dataset */
  downloadUrl?: string;
}

/** Default HuggingFace URLs */
const TINY_STORIES_URLS: Record<string, string> = {
  train: "https://huggingface.co/datasets/roneneldan/TinyStories/resolve/main/TinyStories_all_data.tar.gz",
  validation: "https://huggingface.co/datasets/roneneldan/TinyStories/resolve/main/TinyStories_all_data.tar.gz",
};

// ============================================================
// TinyStoriesDataset
// ============================================================

export class TinyStoriesDataset {
  private corpus: TextCorpus;
  private config: Required<Omit<TinyStoriesConfig, "downloadUrl">>;

  private constructor(
    corpus: TextCorpus,
    config: Required<Omit<TinyStoriesConfig, "downloadUrl">>
  ) {
    this.corpus = corpus;
    this.config = config;
  }

  // ============================================================
  // Static factory
  // ============================================================

  /**
   * Load TinyStories dataset.
   *
   * Checks local cache first. If not cached, downloads from
   * HuggingFace and caches for future use.
   *
   * @param config — dataset configuration
   * @returns Initialized TinyStoriesDataset
   */
  static async load(config: TinyStoriesConfig = {}): Promise<TinyStoriesDataset> {
    const resolved = TinyStoriesDataset.resolveConfig(config);
    const cacheFile = TinyStoriesDataset.getCachePath(resolved);

    // Check cache
    if (fs.existsSync(cacheFile)) {
      const corpus = new TextCorpus(
        { type: "file", path: cacheFile },
        { maxDocuments: resolved.maxStories }
      );
      return new TinyStoriesDataset(corpus, resolved);
    }

    // Download
    const url = config.downloadUrl ?? TINY_STORIES_URLS[resolved.split];
    const corpus = await TextCorpus.loadAsync(
      { type: "url", url, cachePath: cacheFile },
      { maxDocuments: resolved.maxStories }
    );
    return new TinyStoriesDataset(corpus, resolved);
  }

  /**
   * Synchronous load from a local file (no download).
   * Use when you've already downloaded the dataset.
   */
  static loadFromFile(
    filePath: string,
    config: TinyStoriesConfig = {}
  ): TinyStoriesDataset {
    const resolved = TinyStoriesDataset.resolveConfig(config);
    if (!fs.existsSync(filePath)) {
      throw new Error(
        `TinyStoriesDataset.loadFromFile: file not found: ${filePath}`
      );
    }
    const corpus = new TextCorpus(
      { type: "file", path: filePath },
      { maxDocuments: resolved.maxStories }
    );
    return new TinyStoriesDataset(corpus, resolved);
  }

  /**
   * Create from in-memory string array (for testing).
   */
  static fromTexts(texts: string[], config: TinyStoriesConfig = {}): TinyStoriesDataset {
    const resolved = TinyStoriesDataset.resolveConfig(config);
    const corpus = new TextCorpus(
      { type: "inline", texts },
      { maxDocuments: resolved.maxStories }
    );
    return new TinyStoriesDataset(corpus, resolved);
  }

  // ============================================================
  // Public API
  // ============================================================

  /** Total number of stories loaded */
  get length(): number {
    return this.corpus.length;
  }

  /** Dataset split name */
  get split(): string {
    return this.config.split;
  }

  /** Get a single story by index */
  getStory(index: number): string {
    return this.corpus.get(index);
  }

  /** Get underlying TextCorpus */
  getCorpus(): TextCorpus {
    return this.corpus;
  }

  /** Iterate over all stories */
  *[Symbol.iterator](): Iterator<string> {
    yield* this.corpus;
  }

  /**
   * Get stories as an array of strings.
   */
  stories(): string[] {
    return this.corpus.documents();
  }

  // ============================================================
  // Training data generation
  // ============================================================

  /**
   * Create encoded token sequences for training.
   *
   * Encodes all stories with the given tokenizer and returns
   * the concatenated token ID sequence.
   *
   * @param tokenizer — tokenizer to use for encoding
   * @returns Flat array of all token IDs across all stories
   */
  encodeAll(tokenizer: ITokenizer): number[] {
    const allIds: number[] = [];
    for (const story of this.corpus) {
      const ids = tokenizer.encode(story);
      if (ids.length > 0) {
        allIds.push(...ids);
      }
    }
    return allIds;
  }

  // ============================================================
  // Internal
  // ============================================================

  private static resolveConfig(
    config: TinyStoriesConfig
  ): Required<Omit<TinyStoriesConfig, "downloadUrl">> {
    return {
      split: config.split ?? "train",
      maxStories: config.maxStories ?? Infinity,
      cacheDir: config.cacheDir ?? path.join(process.cwd(), ".cache", "minimind"),
    };
  }

  private static getCachePath(
    config: Required<Omit<TinyStoriesConfig, "downloadUrl">>
  ): string {
    const dir = config.cacheDir;
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    return path.join(dir, `TinyStories-${config.split}.jsonl`);
  }
}
